using System;
using UnityEngine;
namespace AgentHands {
// World-space text also renders in stereo; no IMGUI-only headset panel.
public class GestureDebugPanel:MonoBehaviour {
 public GestureRuntime Runtime;public float PlaybackTime;public bool Visible=false;public string RawOverride,ErrorOverride,TrackingStatus;TextMesh text;GameObject backing;
 void LateUpdate(){if(Camera.main==null||Runtime==null)return;if(text==null){var g=new GameObject("GestureEvent debug panel");g.transform.SetParent(Camera.main.transform,false);g.transform.localPosition=new Vector3(-.23f,.182f,.55f);var bg=GameObject.CreatePrimitive(PrimitiveType.Quad);bg.name="Debug contrast backing";UnityEngine.Object.Destroy(bg.GetComponent<Collider>());bg.transform.SetParent(Camera.main.transform,false);bg.transform.localPosition=new Vector3(0,0,.58f);bg.transform.localScale=new Vector3(.565f,.45f,1);var material=new Material(Resources.Load<Material>("AgentHandMaterial"));material.color=new Color(.015f,.025f,.045f);bg.GetComponent<Renderer>().sharedMaterial=material;backing=bg;text=g.AddComponent<TextMesh>();text.richText=false;text.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");g.GetComponent<MeshRenderer>().sharedMaterial=text.font.material;text.characterSize=.00268f;text.fontSize=48;text.anchor=TextAnchor.UpperLeft;}
 text.gameObject.SetActive(Visible);if(backing!=null)backing.SetActive(Visible);if(!Visible)return;var p=Runtime.Plan;string raw=RawOverride??p?.tagged??"(No model response yet)";string words=p?.response??"";var tokens=string.IsNullOrWhiteSpace(words)?Array.Empty<string>():System.Text.RegularExpressions.Regex.Split(words.Trim(),@"\s+");float end=p?.responseDuration??0;if(p!=null)foreach(var e in p.events)end=Mathf.Max(end,e.start+e.duration);int current=Mathf.Clamp((int)(PlaybackTime/Mathf.Max(.1f,end)*tokens.Length),0,Mathf.Max(0,tokens.Length-1));if(p?.wordStarts!=null&&p.wordStarts.Length==tokens.Length){current=0;while(current+1<p.wordStarts.Length&&p.wordStarts[current+1]<=PlaybackTime)current++;}string active="";if(p!=null)foreach(var e in p.events)if(PlaybackTime>=e.start&&PlaybackTime<e.start+e.duration)active+=e.id+" -> "+e.targetId+" / "+e.hand+"\n";
 text.text=Wrap("GestureEvent debug | X toggle | "+Runtime.State+"\n"+TrackingStatus+"\nRAW MODEL (before TTS stripping):\n"+raw+"\nPARSED ACTIVE EVENTS:\n"+active+"\nCURRENT WORD (heuristic, not forced alignment):\n"+(tokens.Length>0&&PlaybackTime>=0&&PlaybackTime<end?tokens[current]:"(no active speech)")+"\nDIAGNOSTICS:\n"+(ErrorOverride??Runtime.Diagnostics),55);
 }
 static string Wrap(string s,int width){var b=new System.Text.StringBuilder();int col=0;foreach(char c in s){b.Append(c);if(c=='\n')col=0;else if(++col>=width){b.Append('\n');col=0;}}return b.ToString();}
}}
